// Display-only lexer: raw source, whitespace and comments stay unchanged.
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const keywords=new Set(`REPORT PROGRAM TABLES DATA TYPES CONSTANTS STATICS FIELD-SYMBOLS TYPE LIKE STANDARD SORTED HASHED TABLE OF REF TO WITH EMPTY DEFAULT KEY UNIQUE NON-UNIQUE BEGIN END OCCURS RANGES SELECT-OPTIONS PARAMETERS SELECTION-SCREEN INITIALIZATION START-OF-SELECTION END-OF-SELECTION AT LOAD-OF-PROGRAM OUTPUT INPUT EXIT-COMMAND ON VALUE-REQUEST HELP-REQUEST RADIOBUTTON GROUP MODIF ID OBLIGATORY DEFAULT CHECKBOX AS USER-COMMAND SELECT SINGLE DISTINCT FROM INNER LEFT RIGHT OUTER JOIN ON WHERE INTO APPENDING CORRESPONDING FIELDS TABLE ORDER BY ASCENDING DESCENDING PRIMARY UP ROWS GROUP HAVING SUM COUNT MAX MIN AVG FOR ALL ENTRIES IN ENDSELECT INSERT UPDATE MODIFY DELETE SORT STABLE COLLECT APPEND LINES READ BINARY SEARCH ASSIGN ASSIGNING COMPONENT FIELD-SYMBOL UNASSIGN TRANSPORTING NO FIELDS LOOP ENDLOOP DO ENDDO WHILE ENDWHILE IF ELSE ELSEIF ENDIF CASE WHEN OTHERS ENDCASE CHECK CONTINUE EXIT RETURN STOP LEAVE SCREEN CALL TRANSACTION AND SKIP FIRST COMMIT WORK WAIT ROLLBACK SET PARAMETER GET MEMORY EXPORT IMPORT FREE CLEAR REFRESH MOVE MOVE-CORRESPONDING WRITE TO CONDENSE CONCATENATE SPLIT REPLACE SHIFT TRANSLATE CONVERT MESSAGE DISPLAY NUMBER USING CHANGING TABLES EXPORTING IMPORTING RECEIVING RETURNING EXCEPTIONS RAISING CREATE OBJECT EXCEPTION RAISE TRY CATCH CLEANUP ENDTRY IS INITIAL NOT BOUND ASSIGNED SUPPLIED REQUESTED AND OR XOR EQ NE GT GE LT LE CP NP CS NS CO CN CA NA BETWEEN ABAP_TRUE ABAP_FALSE SPACE SY-SUBRC SY-TABIX SY-INDEX SY-UCOMM SY-REPID SY-DYNNR SY-DATUM SY-UZEIT SY-UNAME VALUE BASE OPTIONAL NEW CONV CAST CORRESPONDING EXACT REF COND SWITCH REDUCE FILTER FOR LET IN INDEX UNTIL THEN NEXT INIT RESULT LINE_EXISTS LINE_INDEX LINES XSDBOOL BOOLC BOOLX STRING XSTRING I INT8 F P C N D T ABAP_BOOL CHAR1 ICON_D FUNCTION-POOL FUNCTION ENDFUNCTION FORM ENDFORM PERFORM MODULE ENDMODULE CLASS ENDCLASS DEFINITION IMPLEMENTATION DEFERRED PUBLIC PROTECTED PRIVATE SECTION METHODS CLASS-METHODS METHOD ENDMETHOD INTERFACES INTERFACE ENDINTERFACE ALIASES EVENTS CLASS-EVENTS FOR EVENT HANDLER SET PF-STATUS TITLEBAR ENABLE DISABLE INCLUDE SUBMIT VIA SELECTION-SET AUTHORITY-CHECK STATICS DEFINE END-OF-DEFINITION PROCESS BEFORE AFTER CHAIN ENDCHAIN REQUEST SELECT-SCREEN DEFINE VIEW ENTITY ROOT CUSTOM ABSTRACT ASSOCIATION COMPOSITION PROJECTION ANNOTATE EXPOSE AS PROVIDER CONTRACT MANAGED UNMANAGED IMPLEMENTATION STRICT BEHAVIOR MAPPING FIELD READONLY USE LOCK MASTER AUTHORIZATION ETAG DRAFT ACTION VALIDATION DETERMINATION FEATURES INSTANCE UPDATE DELETE CREATE RESULT READ ENTITIES MODIFY ENTITIES REPORTED FAILED MAPPED EXECUTE IN LOCAL MODE`.split(/\s+/));
const control=new Set('FORM ENDFORM MODULE ENDMODULE CLASS ENDCLASS METHOD ENDMETHOD FUNCTION ENDFUNCTION DEFINITION IMPLEMENTATION PROCESS INITIALIZATION START-OF-SELECTION END-OF-SELECTION'.split(' '));
const declarations=new Set('DATA TYPES CONSTANTS STATICS FIELD-SYMBOLS PARAMETERS SELECT-OPTIONS TYPE LIKE'.split(' '));
const types=new Set('STRING XSTRING I INT8 F P C N D T ABAP_BOOL CHAR1 ICON_D'.split(' '));
function scanLine(line,state){const tokens=[];let i=0;const push=(text,kind='')=>tokens.push({text,kind});
 if(!state.quote&&!state.block&&line.startsWith('*'))return[{text:line,kind:'comment'}];
 while(i<line.length){if(state.block){const end=line.indexOf('*/',i);if(end<0){push(line.slice(i),'comment');i=line.length;}else{push(line.slice(i,end+2),'comment');i=end+2;state.block=false;}continue;}
 if(state.quote){const start=i,q=state.quote;while(i<line.length){const c=line[i++];if(q==='|'&&c==='\\'){if(i<line.length)i++;continue;}if(c===q){if(q!=='|'&&line[i]===q){i++;continue;}state.quote=null;break;}}push(line.slice(start,i),'string');continue;}
 const c=line[i];if(c==='"'||line.slice(i,i+2)==='//'){push(line.slice(i),'comment');break;}if(line.slice(i,i+2)==='/*'){state.block=true;continue;}
 if(c==="'"||c==='`'||c==='|'){state.quote=c;push(c,'string');i++;continue;}
 const rest=line.slice(i),space=rest.match(/^\s+/);if(space){push(space[0]);i+=space[0].length;continue;}
 const symbol=rest.match(/^<[A-Za-z_][\w-]*>/);if(symbol){push(symbol[0],'variable');i+=symbol[0].length;continue;}
 const number=rest.match(/^\d+(?:\.\d+)?\b/);if(number){push(number[0],'number');i+=number[0].length;continue;}
 const word=rest.match(/^[A-Za-z_%][A-Za-z0-9_/%-]*/);if(word){const text=word[0],upper=text.toUpperCase(),previous=line.slice(0,i);let kind=keywords.has(upper)?(control.has(upper)?'control':types.has(upper)?'type':declarations.has(upper)?'declaration':'keyword'):/^(?:g[stv]_\w+|l[stv]_\w+|p[av]_\w+|s[oy]_|gcl_|lcl_|[els]s?_)/i.test(text)?'variable':/\b(?:FORM|PERFORM|METHOD|MODULE|FUNCTION)\s*$/i.test(previous)||/(?:->|=>)\s*$/.test(previous)?'function':'';push(text,kind);i+=text.length;continue;}
 const operator=rest.match(/^(?:->|=>|<=|>=|<>|&&|[=+*/<>#@&~])/);if(operator){push(operator[0],'operator');i+=operator[0].length;continue;}push(c);i++;
 }
 return tokens;}
export function tokenizeCode(code){const state={quote:null,block:false};return String(code).split('\n').map(raw=>({raw,tokens:scanLine(raw,state)}));}
export function procedures(code){const list=[];for(const [i,line] of tokenizeCode(code).entries()){const words=line.tokens.filter(t=>t.kind!=='comment'&&t.kind!=='string'&&t.text.trim());if(words[0]?.text.toUpperCase()==='FORM'&&words[1])list.push({name:words[1].text,line:i+1,index:list.length});}return list;}
export function highlightCode(code,{numbers=true,sections=true}={}){let form=-1,inForm=false;return tokenizeCode(code).map((line,i)=>{const words=line.tokens.filter(t=>t.kind!=='comment'&&t.kind!=='string'&&t.text.trim()),first=words[0]?.text.toUpperCase(),start=sections&&first==='FORM'&&words[1],end=sections&&first==='ENDFORM';if(start){form++;inForm=true;}const classes=['code-line','abap-line'];if(inForm)classes.push('form-color-'+form%5);if(start)classes.push('form-start');if(end&&inForm)classes.push('form-end');const data=start?` data-form-name="${esc(words[1].text)}"`:'';const rendered=line.tokens.map(t=>t.kind?`<span class="abap-${t.kind}">${esc(t.text)}</span>`:esc(t.text)).join('');const html=`<span class="${classes.join(' ')}" data-code-line="${i+1}"${data}>${numbers?`<span class="line-number" data-line="${i+1}" aria-hidden="true"></span>`:''}<span class="code-content">${rendered}</span></span>`;if(end)inForm=false;return html;}).join('');}
export function procedureTools(code,blockIndex){const forms=procedures(code);if(!forms.length)return '';return `<div class="form-navigation"><label>FORM 바로가기 <select data-form-jump data-code-block="${blockIndex}" aria-label="이 코드의 FORM으로 이동"><option value="">${forms.length}개 FORM 중 선택</option>${forms.map(f=>`<option value="${f.line}">${esc(f.name)} · ${f.line}줄</option>`).join('')}</select></label><span>같은 색의 시작·끝이 한 FORM이에요.</span></div>`;}
